const r = $json;

// Recuperamos datos del evento de MinIO para poder mover luego el PDF original
let minioEvent = {};
try {
  minioEvent = $('Code - Extraer evento MinIO').first().json || {};
} catch (error) {
  minioEvent = {};
}

const originalKey = minioEvent.original_key || r.original_key || null;
const originalBucket = minioEvent.bucket || r.original_bucket || 'preflight-pdf';

function esc(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function boolText(value) {
  if (value === true) return 'Sí';
  if (value === false) return 'No';
  return 'No detectado';
}

function formatBox(box) {
  if (!box) return 'No detectado';

  const width = box.width_mm ?? 'N/D';
  const height = box.height_mm ?? 'N/D';

  return `${width} x ${height} mm`;
}

function boxDescription(name) {
  const descriptions = {
    MediaBox:
      'Define el tamaño total físico de la página PDF. Suele ser el área más grande del documento.',
    CropBox:
      'Define el límite para el contenido de una página cuando se muestra o imprime.',
    ArtBox:
      'Define el contenido significativo de la página, incluido el espacio en blanco.',
    TrimBox:
      'Define las dimensiones finales de la página después del recorte.',
    BleedBox:
      'Define la ruta de recorte cuando la página se imprime profesionalmente para permitir el recorte y plegado del papel. Las marcas de impresión pueden quedar fuera del área de sangrado.',
  };

  return descriptions[name] || 'Sin descripción.';
}

const filename = r.filename || minioEvent.filename || 'documento.pdf';
const baseName = filename.replace(/\.pdf$/i, '');

const status = r.result?.status || r.status || 'DESCONOCIDO';
const issues = r.result?.issues || r.issues || [];

const pages = r.pdfinfo?.pages ?? 'No detectado';
const encrypted = r.pdfinfo?.encrypted ?? 'No detectado';

// Cajas PDF
const boxes = r.pdfinfo?.boxes || {};

const mediaBox = boxes.MediaBox || null;
const cropBox = boxes.CropBox || null;
const bleedBox = boxes.BleedBox || null;
const trimBox = boxes.TrimBox || null;
const artBox = boxes.ArtBox || null;

// Tamaño principal en milímetros
const pageSize = r.pdfinfo?.page_size_mm || {};

const pageWidth = pageSize.width ?? trimBox?.width_mm ?? mediaBox?.width_mm ?? null;
const pageHeight = pageSize.height ?? trimBox?.height_mm ?? mediaBox?.height_mm ?? null;

let pageSizeSource = pageSize.source || null;

if (!pageSizeSource) {
  if (trimBox) {
    pageSizeSource = 'TrimBox';
  } else if (mediaBox) {
    pageSizeSource = 'MediaBox';
  } else {
    pageSizeSource = 'No detectado';
  }
}

// Sangre
const bleed = r.bleed || {};
const bleedDeclared = bleed.bleed_declared;
const bleedEstimated = bleed.bleed_estimated_mm ?? 0;
const bleedMm = bleed.bleed_mm || {};

// Color / ICC
const colorProfile = r.color_profile || {};
const profileDescription = colorProfile.profile_description || 'No detectado';
const profileType = colorProfile.profile_type || 'No detectado';

// Cobertura de tinta
const ink = r.ink_coverage || {};
const inkPages = ink.pages || [];
const highInkPages = ink.high_total_ink_pages_over_300 || [];

const firstInkPage = inkPages[0] || {};

const c = firstInkPage.c != null ? Math.round(firstInkPage.c * 10000) / 100 : null;
const m = firstInkPage.m != null ? Math.round(firstInkPage.m * 10000) / 100 : null;
const y = firstInkPage.y != null ? Math.round(firstInkPage.y * 10000) / 100 : null;
const k = firstInkPage.k != null ? Math.round(firstInkPage.k * 10000) / 100 : null;

const totalInk = firstInkPage.total_ink_percent_estimated ?? null;

const issuesHtml = issues.length
  ? issues.map(issue => `<li>${esc(issue)}</li>`).join('\n')
  : '<li>No se han detectado incidencias según las reglas actuales.</li>';

const statusClass = status === 'OK' ? 'ok' : status === 'ERROR' ? 'error' : 'review';

const html = `<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <title>Informe Preflight - ${esc(filename)}</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #222;
      line-height: 1.45;
      margin: 32px;
    }

    h1, h2 {
      margin-bottom: 8px;
    }

    .status {
      display: inline-block;
      padding: 8px 14px;
      border-radius: 6px;
      font-weight: bold;
      color: white;
    }

    .ok {
      background: #198754;
    }

    .review {
      background: #d97706;
    }

    .error {
      background: #dc2626;
    }

    table {
      border-collapse: collapse;
      width: 100%;
      margin: 12px 0 24px;
    }

    th, td {
      border: 1px solid #ddd;
      padding: 8px 10px;
      text-align: left;
      vertical-align: top;
    }

    th {
      background: #f3f3f3;
      width: 32%;
    }

    .small {
      color: #666;
      font-size: 12px;
    }

    .note {
      color: #555;
      font-size: 13px;
    }
  </style>
</head>
<body>
  <h1>Informe Preflight PDF</h1>

  <p><strong>Archivo:</strong> ${esc(filename)}</p>
  <p><strong>Estado:</strong> <span class="status ${statusClass}">${esc(status)}</span></p>

  <h2>Resumen</h2>
  <table>
    <tr>
      <th>Páginas</th>
      <td>${esc(pages)}</td>
    </tr>
    <tr>
      <th>Tamaño final</th>
      <td>${pageWidth && pageHeight ? `${esc(pageWidth)} x ${esc(pageHeight)} mm` : 'No detectado'}</td>
    </tr>
    <tr>
      <th>Fuente del tamaño</th>
      <td>${esc(pageSizeSource)}</td>
    </tr>
    <tr>
      <th>PDF cifrado/protegido</th>
      <td>${esc(encrypted)}</td>
    </tr>
  </table>

  <h2>Cajas PDF / Áreas de página</h2>
  <table>
    <tr>
      <th>Caja PDF</th>
      <th>Medida detectada</th>
      <th>Descripción</th>
    </tr>
    <tr>
      <td><strong>MediaBox</strong></td>
      <td>${esc(formatBox(mediaBox))}</td>
      <td>${esc(boxDescription('MediaBox'))}</td>
    </tr>
    <tr>
      <td><strong>CropBox</strong></td>
      <td>${esc(formatBox(cropBox))}</td>
      <td>${esc(boxDescription('CropBox'))}</td>
    </tr>
    <tr>
      <td><strong>ArtBox</strong></td>
      <td>${esc(formatBox(artBox))}</td>
      <td>${esc(boxDescription('ArtBox'))}</td>
    </tr>
    <tr>
      <td><strong>TrimBox</strong></td>
      <td>${esc(formatBox(trimBox))}</td>
      <td>${esc(boxDescription('TrimBox'))}</td>
    </tr>
    <tr>
      <td><strong>BleedBox</strong></td>
      <td>${esc(formatBox(bleedBox))}</td>
      <td>${esc(boxDescription('BleedBox'))}</td>
    </tr>
  </table>

  <h2>Sangre</h2>
  <table>
    <tr>
      <th>Sangre declarada</th>
      <td>${boolText(bleedDeclared)}</td>
    </tr>
    <tr>
      <th>Sangre estimada</th>
      <td>${esc(bleedEstimated)} mm</td>
    </tr>
    <tr>
      <th>Izquierda</th>
      <td>${esc(bleedMm.left ?? 0)} mm</td>
    </tr>
    <tr>
      <th>Derecha</th>
      <td>${esc(bleedMm.right ?? 0)} mm</td>
    </tr>
    <tr>
      <th>Superior</th>
      <td>${esc(bleedMm.top ?? 0)} mm</td>
    </tr>
    <tr>
      <th>Inferior</th>
      <td>${esc(bleedMm.bottom ?? 0)} mm</td>
    </tr>
  </table>

  <h2>Color e ICC</h2>
  <table>
    <tr>
      <th>Perfil ICC</th>
      <td>${esc(profileDescription)}</td>
    </tr>
    <tr>
      <th>Tipo de perfil</th>
      <td>${esc(profileType)}</td>
    </tr>
    <tr>
      <th>Parece RGB</th>
      <td>${boolText(colorProfile.seems_rgb)}</td>
    </tr>
    <tr>
      <th>Parece perfil de impresión</th>
      <td>${boolText(colorProfile.seems_print_profile)}</td>
    </tr>
  </table>

  <h2>Cobertura de tinta aproximada</h2>
  <table>
    <tr>
      <th>C</th>
      <td>${c != null ? `${esc(c)}%` : 'No detectado'}</td>
    </tr>
    <tr>
      <th>M</th>
      <td>${m != null ? `${esc(m)}%` : 'No detectado'}</td>
    </tr>
    <tr>
      <th>Y</th>
      <td>${y != null ? `${esc(y)}%` : 'No detectado'}</td>
    </tr>
    <tr>
      <th>K</th>
      <td>${k != null ? `${esc(k)}%` : 'No detectado'}</td>
    </tr>
    <tr>
      <th>Total tinta estimado</th>
      <td>${totalInk != null ? `${esc(totalInk)}%` : 'No detectado'}</td>
    </tr>
    <tr>
      <th>Páginas sobre 300%</th>
      <td>${highInkPages.length ? esc(highInkPages.join(', ')) : 'No detectadas'}</td>
    </tr>
  </table>

  <h2>Incidencias</h2>
  <ul>
    ${issuesHtml}
  </ul>

  <p class="small">
    Informe generado automáticamente. Este análisis es orientativo y debe validarse con herramientas profesionales de preflight para producción crítica.
  </p>
</body>
</html>`;

const reportJsonText = JSON.stringify(r, null, 2);

return {
  json: {
    filename,
    status,
    issues,
    pages,

    original_key: originalKey,
    original_bucket: originalBucket,

    page_size_mm: {
      width: pageWidth,
      height: pageHeight,
      source: pageSizeSource,
    },

    pdf_boxes: {
      MediaBox: {
        size_mm: formatBox(mediaBox),
        description: boxDescription('MediaBox'),
      },
      CropBox: {
        size_mm: formatBox(cropBox),
        description: boxDescription('CropBox'),
      },
      ArtBox: {
        size_mm: formatBox(artBox),
        description: boxDescription('ArtBox'),
      },
      TrimBox: {
        size_mm: formatBox(trimBox),
        description: boxDescription('TrimBox'),
      },
      BleedBox: {
        size_mm: formatBox(bleedBox),
        description: boxDescription('BleedBox'),
      },
    },

    bleed_declared: bleedDeclared,
    bleed_estimated_mm: bleedEstimated,

    icc_profile: profileDescription,
    icc_profile_type: profileType,

    report_html_filename: `${baseName}_preflight.html`,
    report_json_filename: `${baseName}_preflight.json`,

    report_html: html,
    report_json: reportJsonText,

    analysis: r,
  },
  binary: {
    report_html: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: `${baseName}_preflight.html`,
    },
    report_json: {
      data: Buffer.from(reportJsonText, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: `${baseName}_preflight.json`,
    },
  },
};

const informe = $('Code - Preparar informe').first().json;
const destino = $('Code - Preparar destino PDF').first().json;

const issues = informe.issues || [];

const issuesText = issues.length
  ? issues.map(i => `- ${i}`).join('\n')
  : '- Sin incidencias detectadas según las reglas actuales.';

const htmlKey = `informes/${informe.report_html_filename}`;
const jsonKey = `informes/${informe.report_json_filename}`;

const whatsappMessage = `📄 Informe Preflight PDF

Archivo: ${informe.filename}
Estado: ${informe.status}
Páginas: ${informe.pages}
Tamaño: ${informe.page_size_mm?.width ?? 'N/D'} x ${informe.page_size_mm?.height ?? 'N/D'} mm
Fuente tamaño: ${informe.page_size_mm?.source ?? 'N/D'}

Sangre declarada: ${informe.bleed_declared ? 'Sí' : 'No'}
Sangre estimada: ${informe.bleed_estimated_mm ?? 'N/D'} mm

ICC: ${informe.icc_profile}
Tipo ICC: ${informe.icc_profile_type}

Incidencias:
${issuesText}`;

return {
  json: {
    status: 'preflight_completado',
    filename: informe.filename,
    preflight_status: informe.status,
    pages: informe.pages,
    page_size_mm: informe.page_size_mm,
    bleed_declared: informe.bleed_declared,
    bleed_estimated_mm: informe.bleed_estimated_mm,
    icc_profile: informe.icc_profile,
    icc_profile_type: informe.icc_profile_type,
    issues,
    minio: {
      bucket: 'preflight-pdf',
      html_key: htmlKey,
      json_key: jsonKey,
      moved_pdf_key: destino.destination_key,
      original_key_deleted: destino.original_key,
    },
    whatsapp_message: whatsappMessage,
  },
};

const informe = $json;

const filename = informe.filename || 'documento.pdf';
const status = informe.status || 'ERROR';
const originalKey = informe.original_key;

if (!originalKey) {
  throw new Error('No se ha encontrado original_key. Revisa el nodo Code - Preparar informe.');
}

let destinationFolder = 'error';

if (status === 'OK') {
  destinationFolder = 'ok';
} else if (status === 'REVISAR') {
  destinationFolder = 'revisar';
} else {
  destinationFolder = 'error';
}

return {
  json: {
    filename,
    status,
    original_key: originalKey,
    destination_folder: destinationFolder,
    destination_key: `${destinationFolder}/${filename}`,
    bucket: informe.original_bucket || 'preflight-pdf',
  },
};

const output = [];

const GROUP_ID = '120363425302477785@g.us';

function sanitizeFilename(name) {
  return String(name || 'documento.pdf')
    .replace(/[\\/:*?"<>|]/g, '_')
    .replace(/\s+/g, '_')
    .trim();
}

function findDocumentMessage(message) {
  if (!message || typeof message !== 'object') return null;

  if (message.documentMessage) {
    return message.documentMessage;
  }

  if (message.documentWithCaptionMessage?.message?.documentMessage) {
    return message.documentWithCaptionMessage.message.documentMessage;
  }

  if (message.viewOnceMessage?.message?.documentMessage) {
    return message.viewOnceMessage.message.documentMessage;
  }

  if (message.ephemeralMessage?.message?.documentMessage) {
    return message.ephemeralMessage.message.documentMessage;
  }

  if (message.ephemeralMessage?.message?.documentWithCaptionMessage?.message?.documentMessage) {
    return message.ephemeralMessage.message.documentWithCaptionMessage.message.documentMessage;
  }

  return null;
}

for (const item of items) {
  const payload = item.json.body || item.json;
  const data = payload.data || payload;
  const key = data.key || data.message?.key || {};

  const remoteJid = key.remoteJid || data.remoteJid || '';
  const fromMe = key.fromMe === true;
  const messageId = key.id || data.id || '';

  const message = data.message || {};
  const documentMessage = findDocumentMessage(message);

  const mimeType =
    documentMessage?.mimetype ||
    documentMessage?.mimeType ||
    data.mimetype ||
    data.mimeType ||
    '';

  const originalFilename =
    documentMessage?.fileName ||
    documentMessage?.title ||
    data.fileName ||
    data.filename ||
    `whatsapp_${messageId}.pdf`;

  const isCorrectGroup = remoteJid === GROUP_ID;

  const isPdf =
    String(mimeType).toLowerCase().includes('pdf') ||
    String(originalFilename).toLowerCase().endsWith('.pdf');

  // Importante:
  // No filtramos por fromMe, porque si tú mandas el PDF desde el WhatsApp conectado
  // a Evolution, viene como fromMe=true y antes se descartaba.
  if (!isCorrectGroup || !isPdf || !messageId) {
    continue;
  }

  const filename = sanitizeFilename(originalFilename);
  const originalKey = `entrada-whatsapp/${filename}`;

  output.push({
    json: {
      instance: payload.instance || 'ADDO v2',
      group_id: remoteJid,
      message_id: messageId,
      message_key: key,
      filename,
      base_name: filename.replace(/\.pdf$/i, ''),
      mime_type: mimeType || 'application/pdf',
      original_key: originalKey,
      original_bucket: 'preflight-pdf',
      from_me: fromMe,
      push_name: data.pushName || null,
      raw_event: payload,
    },
  });
}

return output;

const meta = $('Code - Filtrar grupo y PDF').first().json;
const response = $json;

function findBase64(obj) {
  if (!obj || typeof obj !== 'object') return null;

  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      const clean = value.replace(/^data:.*?;base64,/, '');

      const keyLooksRight = key.toLowerCase().includes('base64');
      const valueLooksRight =
        value.startsWith('data:application/pdf;base64,') ||
        (clean.length > 500 && /^[A-Za-z0-9+/=\r\n]+$/.test(clean));

      if (keyLooksRight || valueLooksRight) {
        return clean;
      }
    }

    if (value && typeof value === 'object') {
      const found = findBase64(value);
      if (found) return found;
    }
  }

  return null;
}

let base64 =
  response.base64 ||
  response.data?.base64 ||
  response.response?.base64 ||
  response.media?.base64 ||
  findBase64(response);

if (!base64) {
  throw new Error('No se encontró contenido Base64 del PDF en la respuesta de Evolution.');
}

base64 = String(base64).replace(/^data:.*?;base64,/, '').replace(/\s/g, '');

return {
  json: {
    filename: meta.filename,
    base_name: meta.base_name,
    original_key: meta.original_key,
    original_bucket: meta.original_bucket,
    group_id: meta.group_id,
    message_id: meta.message_id,
    mime_type: 'application/pdf',
  },
  binary: {
    file: {
      data: base64,
      mimeType: 'application/pdf',
      fileName: meta.filename,
    },
  },
};

const analysis = $json;
const meta = $('Code - Convertir Base64 a PDF').first().json;

analysis.filename = meta.filename;
analysis.original_key = meta.original_key;
analysis.original_bucket = meta.original_bucket;
analysis.source = 'whatsapp';
analysis.whatsapp = {
  group_id: meta.group_id,
  message_id: meta.message_id,
};

return {
  json: analysis,
};
